import os
import json5


CACHE_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.realpath(__file__))), "cache")
CONFIG_FILE = os.path.join(CACHE_DIR, 'claude_config.json5')


def ensure_cache_dir():
    if not os.path.exists(CACHE_DIR):
        os.makedirs(CACHE_DIR)


def load_config():
    if not os.path.exists(CONFIG_FILE):
        return {}
    with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
        return json5.load(f)


def save_config(config_data):
    ensure_cache_dir()
    with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
        json5.dump(config_data, f, ensure_ascii=False, indent=4)


def get_config():
    return load_config()


def add_new_config(api_key=None, plugin_url=None):
    config = load_config()
    if api_key:
        config["api_key"] = api_key
    if plugin_url:
        config["plugin_url"] = plugin_url
    save_config(config)
    print(f"配置已保存")


def set_api_key(api_key):
    config = load_config()
    config["api_key"] = api_key
    save_config(config)
    print(f"API Key 已设置: {api_key[:10]}...")


def set_plugin_url(plugin_url):
    config = load_config()
    config["plugin_url"] = plugin_url
    save_config(config)
    print(f"插件 URL 已设置: {plugin_url}")


def change_config(api_key=None, plugin_url=None):
    if api_key:
        set_api_key(api_key)
    if plugin_url:
        set_plugin_url(plugin_url)
    if not api_key and not plugin_url:
        print("请提供 --api-key 或 --plugin-url 参数")


def list_configs():
    config = load_config()
    if config:
        print("当前配置:")
        if "api_key" in config:
            print(f"  API Key: {config['api_key'][:10]}...")
        if "plugin_url" in config:
            print(f"  插件 URL: {config['plugin_url']}")
    else:
        print("暂无配置，请使用 ahclaude config --api-key <key> --plugin-url <url> 进行配置")


def delete_config(config_type=None):
    config = load_config()
    if config_type == "api_key":
        if "api_key" in config:
            del config["api_key"]
            save_config(config)
            print("API Key 已删除")
        else:
            print("未找到 API Key 配置")
    elif config_type == "plugin_url":
        if "plugin_url" in config:
            del config["plugin_url"]
            save_config(config)
            print("插件 URL 已删除")
        else:
            print("未找到插件 URL 配置")
    elif config_type == "all":
        if os.path.exists(CONFIG_FILE):
            os.remove(CONFIG_FILE)
            print("所有配置已删除")
        else:
            print("暂无配置可删除")
    else:
        print("请指定要删除的配置类型: api_key, plugin_url, 或 all")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Claude 配置管理工具")
    
    subparsers = parser.add_subparsers(dest="command", help="子命令")
    
    parser_add = subparsers.add_parser("add", aliases=["a"], help="添加配置")
    parser_add.add_argument("--api-key", type=str, help="Claude API Key")
    parser_add.add_argument("--plugin-url", type=str, help="Claude 插件 URL")
    
    parser_set = subparsers.add_parser("set", aliases=["s"], help="设置配置")
    parser_set.add_argument("--api-key", type=str, help="Claude API Key")
    parser_set.add_argument("--plugin-url", type=str, help="Claude 插件 URL")
    
    parser_list = subparsers.add_parser("list", aliases=["l"], help="列出配置")
    
    parser_delete = subparsers.add_parser("delete", aliases=["d"], help="删除配置")
    parser_delete.add_argument("type", nargs="?", choices=["api_key", "plugin_url", "all"], help="配置类型")
    
    args = parser.parse_args()
    
    if args.command in ["add", "a"]:
        add_new_config(args.api_key, args.plugin_url)
    elif args.command in ["set", "s"]:
        change_config(args.api_key, args.plugin_url)
    elif args.command in ["list", "l"]:
        list_configs()
    elif args.command in ["delete", "d"]:
        delete_config(args.type)
    else:
        parser.print_help()
